export class SceneActionRegistry {
    actions = new Map();
    register(name, action) {
        if (!name || this.actions.has(name))
            throw new Error(`Scene action is invalid or already registered: ${name}`);
        this.actions.set(name, action);
        return () => this.actions.delete(name);
    }
    has(name) { return this.actions.has(name); }
    async execute(name, value, context = {}) {
        const action = this.actions.get(name);
        if (!action)
            throw new Error(`Scene action is not registered: ${name}`);
        await action(value, context);
    }
    clear() { this.actions.clear(); }
}